/// Fully validated immutable reference bundle.
struct ReferenceBundle {
    /// Canonical directory containing the manifest and raw vectors.
    root: PathBuf,
    /// Manifest authenticated by [`MANIFEST_SHA256`].
    manifest: Value,
}

impl ReferenceBundle {
    /// Opens a closed, nonsymlink file inventory and authenticates every byte.
    fn open(root: &Path) -> Self {
        let root = root
            .canonicalize()
            .unwrap_or_else(|error| panic!("cannot resolve reference root: {error}"));
        assert!(root.is_dir(), "reference root is not a directory");
        let expected = RAW_FILES
            .iter()
            .map(|file| file.name)
            .chain([MANIFEST_FILE])
            .collect::<BTreeSet<_>>();
        let observed = fs::read_dir(&root)
            .expect("read reference root")
            .map(|entry| {
                let entry = entry.expect("read reference entry");
                let metadata = fs::symlink_metadata(entry.path()).expect("reference metadata");
                assert!(
                    metadata.file_type().is_file(),
                    "reference entries must be regular files"
                );
                assert!(
                    !metadata.file_type().is_symlink(),
                    "reference entries must not be symlinks"
                );
                entry
                    .file_name()
                    .into_string()
                    .expect("reference names must be UTF-8")
            })
            .collect::<BTreeSet<_>>();
        assert_eq!(observed, expected.into_iter().map(str::to_owned).collect());

        let manifest_path = root.join(MANIFEST_FILE);
        let manifest_bytes = fs::read(&manifest_path).expect("read reference manifest");
        assert_eq!(manifest_bytes.len() as u64, MANIFEST_BYTES);
        assert_eq!(sha256(&manifest_bytes), MANIFEST_SHA256);
        let manifest: Value =
            serde_json::from_slice(&manifest_bytes).expect("parse reference JSON");
        assert_manifest_contract(&manifest);

        for file in RAW_FILES {
            let path = root.join(file.name);
            let bytes = fs::read(&path).expect("read reference tensor");
            assert_eq!(bytes.len() as u64, file.bytes, "{} byte length", file.key);
            assert_eq!(sha256(&bytes), file.sha256, "{} SHA-256", file.key);
            let descriptor = manifest
                .pointer(&format!("/tensors/{}", file.key))
                .unwrap_or_else(|| panic!("missing descriptor for {}", file.key));
            assert_eq!(descriptor["relative_path"], json!(file.name));
            assert_eq!(descriptor["bytes"], json!(file.bytes));
            assert_eq!(descriptor["sha256"], json!(file.sha256));
            assert_eq!(descriptor["elements"], json!(file.rows * file.columns));
            assert_eq!(descriptor["encoding"], json!("little_endian_f32"));
            assert_eq!(descriptor["dtype"], json!("F32"));
            assert_eq!(descriptor["summary"]["finite"], json!(true));
        }
        Self { root, manifest }
    }

    /// Reads one authenticated raw tensor as host F32 values.
    fn tensor(&self, key: &str) -> Vec<f32> {
        let file = RAW_FILES
            .iter()
            .find(|file| file.key == key)
            .unwrap_or_else(|| panic!("unknown reference tensor {key}"));
        let bytes = fs::read(self.root.join(file.name)).expect("read authenticated tensor");
        let values = bytes
            .chunks_exact(4)
            .map(|chunk| f32::from_le_bytes(chunk.try_into().expect("four-byte chunk")))
            .collect::<Vec<_>>();
        assert_eq!(values.len(), file.rows * file.columns);
        assert!(values.iter().all(|value| value.is_finite()));
        values
    }

    /// Returns the pinned generation IDs after checking their manifest copy.
    fn greedy_ids(&self) -> Vec<u32> {
        let values = self.manifest["generation"]["token_ids"]
            .as_array()
            .expect("generation token IDs")
            .iter()
            .map(|value| value.as_u64().expect("u32 generation token") as u32)
            .collect::<Vec<_>>();
        assert_eq!(values, GREEDY_IDS);
        values
    }
}

/// Pins semantic fields which explain how every raw vector was produced.
fn assert_manifest_contract(manifest: &Value) {
    assert_eq!(manifest["schema_version"], json!(1));
    assert_eq!(manifest["repository"], json!(REPOSITORY));
    assert_eq!(manifest["revision"], json!(REVISION));
    assert_eq!(
        manifest["reference_class"],
        json!("transformers.T5ForConditionalGeneration")
    );
    assert_eq!(manifest["execution"]["device"], json!("cpu"));
    assert_eq!(manifest["execution"]["dtype"], json!("float32"));
    assert_eq!(
        manifest["execution"]["deterministic_algorithms"],
        json!(true)
    );
    assert_eq!(manifest["execution"]["local_files_only"], json!(true));
    assert_eq!(manifest["execution"]["use_safetensors"], json!(true));
    assert_eq!(
        manifest["provenance"]["generator"]["sha256"],
        json!(GENERATOR_SHA256)
    );
    assert_eq!(
        manifest["provenance"]["generator"]["git_head"],
        json!(GENERATOR_COMMIT)
    );
    assert_eq!(
        manifest["provenance"]["generator"]["git_dirty"],
        json!(false)
    );
    assert_eq!(
        manifest["provenance"]["artifact_manifest_sha256"],
        json!(ARTIFACT_MANIFEST_SHA256)
    );
    assert_eq!(
        manifest["provenance"]["checkpoint"]["inventory_sha256"],
        json!(HEADER_INVENTORY_SHA256)
    );
    assert_eq!(manifest["provenance"]["checkpoint"]["tensors"], json!(190));
    assert_eq!(
        manifest["provenance"]["checkpoint"]["tensor_bytes"],
        json!(307_844_608_u64)
    );
    assert_eq!(
        manifest["provenance"]["parameter_count"],
        json!(76_961_152_u64)
    );
    let artifacts = manifest["provenance"]["artifacts"]
        .as_array()
        .expect("artifact records");
    assert_eq!(artifacts.len(), ARTIFACT_FILES.len());
    for expected in ARTIFACT_FILES {
        let artifact = artifacts
            .iter()
            .find(|artifact| artifact["relative_path"] == expected.name)
            .unwrap_or_else(|| panic!("missing artifact record for {}", expected.name));
        assert_eq!(artifact["bytes"], json!(expected.bytes));
        assert_eq!(artifact["sha256"], json!(expected.sha256));
    }
    assert_eq!(
        manifest["runtime_config"]["serialized_tie_word_embeddings"],
        json!(false)
    );
    assert_eq!(
        manifest["runtime_config"]["normalized_tie_word_embeddings"],
        json!(true)
    );
    assert_eq!(
        manifest["runtime_config"]["scale_decoder_outputs"],
        json!(false)
    );
    assert_eq!(
        manifest["runtime_config"]["lm_head_is_independent"],
        json!(true)
    );
    assert_eq!(manifest["generation"]["prompt"], json!(LONG_PROMPT));
    assert_eq!(
        manifest["generation"]["source_token_ids"],
        json!(LONG_SOURCE_IDS)
    );
    assert_eq!(
        manifest["generation"]["max_new_tokens"],
        json!(GREEDY_DECISIONS)
    );
    assert_eq!(manifest["generation"]["first_eos_position"], Value::Null);
    assert!(
        manifest["generation"]["minimum_margin"]
            .as_f64()
            .expect("minimum margin")
            > 0.45
    );
    assert!(
        manifest["generation"]["cached_teacher_parity"]["cosine"]
            .as_f64()
            .expect("parity cosine")
            >= 0.999_999
    );
    assert_eq!(
        manifest["generation"]["cached_teacher_parity"]["failure_count_at_atol_rtol_1e_4"],
        json!(0)
    );
    assert_eq!(
        manifest["beam_generation"]["prompt"],
        json!(TRANSLATION_PROMPT)
    );
    assert_eq!(
        manifest["beam_generation"]["source_token_ids"],
        json!(TRANSLATION_IDS)
    );
    assert_eq!(manifest["beam_generation"]["token_ids"], json!(BEAM_IDS));
    assert_eq!(manifest["beam_generation"]["num_beams"], json!(4));
    assert_eq!(manifest["beam_generation"]["finish_reason"], json!("eos:1"));
    assert_eq!(manifest["context_boundary"]["source_length"], json!(512));
    assert_eq!(
        manifest["context_boundary"]["token_ids_u32le_sha256"],
        json!(BOUNDARY_IDS_SHA256)
    );
    assert_eq!(
        manifest["padded_batch"]["individual_parity"]["failure_count_at_atol_rtol_1e_4"],
        json!(0)
    );
    for package in [
        "numpy",
        "safetensors",
        "tokenizers",
        "torch",
        "transformers",
    ] {
        assert!(
            manifest["environment"]["packages"]
                .as_array()
                .expect("package records")
                .iter()
                .any(|record| record["name"] == package)
        );
    }
}

/// SHA-256 over arbitrary bytes.
fn sha256(bytes: &[u8]) -> String {
    format!("{:x}", Sha256::digest(bytes))
}

/// Streams SHA-256 without retaining the complete checkpoint in host memory.
fn sha256_file(path: &Path) -> String {
    let mut file = fs::File::open(path)
        .unwrap_or_else(|error| panic!("open {} for hashing: {error}", path.display()));
    let mut digest = Sha256::new();
    let mut buffer = vec![0_u8; 1024 * 1024];
    loop {
        let read = file
            .read(&mut buffer)
            .unwrap_or_else(|error| panic!("hash {}: {error}", path.display()));
        if read == 0 {
            break;
        }
        digest.update(&buffer[..read]);
    }
    format!("{:x}", digest.finalize())
}

/// Authenticates the closed pinned artifact set before allocating model parameters.
fn authenticate_checkpoint(root: &Path) -> PathBuf {
    let root = root
        .canonicalize()
        .unwrap_or_else(|error| panic!("cannot resolve checkpoint root: {error}"));
    assert!(root.is_dir(), "checkpoint root is not a directory");
    let expected = ARTIFACT_FILES
        .iter()
        .map(|file| file.name.to_owned())
        .collect::<BTreeSet<_>>();
    let mut observed = BTreeSet::new();
    for entry in fs::read_dir(&root).expect("read checkpoint root") {
        let entry = entry.expect("read checkpoint entry");
        let name = entry
            .file_name()
            .into_string()
            .expect("checkpoint names must be UTF-8");
        let metadata = fs::symlink_metadata(entry.path()).expect("checkpoint entry metadata");
        assert!(
            !metadata.file_type().is_symlink(),
            "checkpoint entries must not be symlinks"
        );
        if name == ".cache" {
            assert!(metadata.is_dir(), ".cache must be a regular directory");
            continue;
        }
        assert!(
            metadata.file_type().is_file(),
            "unexpected non-file checkpoint entry {name}"
        );
        observed.insert(name);
    }
    assert_eq!(observed, expected, "checkpoint root inventory");
    for expected in ARTIFACT_FILES {
        let path = root.join(expected.name);
        let metadata = fs::symlink_metadata(&path).expect("checkpoint artifact metadata");
        assert_eq!(
            metadata.len(),
            expected.bytes,
            "{} byte length",
            expected.name
        );
        assert_eq!(
            sha256_file(&path),
            expected.sha256,
            "{} SHA-256",
            expected.name
        );
    }
    root
}

/// Stable numerical comparison for one complete reference tensor.
#[derive(Debug)]
struct Comparison {
    /// F64 cosine over all values.
    cosine: f64,
    /// Greatest elementwise absolute difference.
    maximum_absolute_error: f64,
    /// Count outside `atol + rtol * abs(reference)` at `1e-4` each.
    tolerance_failures: usize,
    /// SHA-256 over actual little-endian F32 values.
    actual_sha256: String,
}

/// Compares full vectors without silently accepting non-finite values.
fn compare(label: &str, actual: &[f32], expected: &[f32]) -> Comparison {
    assert_eq!(actual.len(), expected.len(), "{label} length");
    let mut dot = 0.0_f64;
    let mut left_norm = 0.0_f64;
    let mut right_norm = 0.0_f64;
    let mut maximum_absolute_error = 0.0_f64;
    let mut tolerance_failures = 0_usize;
    let mut actual_bytes = Vec::with_capacity(actual.len() * 4);
    for (index, (&left, &right)) in actual.iter().zip(expected).enumerate() {
        assert!(
            left.is_finite(),
            "{label} actual value {index} is non-finite"
        );
        assert!(
            right.is_finite(),
            "{label} reference value {index} is non-finite"
        );
        let left = f64::from(left);
        let right = f64::from(right);
        dot += left * right;
        left_norm += left * left;
        right_norm += right * right;
        let difference = (left - right).abs();
        maximum_absolute_error = maximum_absolute_error.max(difference);
        tolerance_failures += usize::from(difference > 1.0e-4 + 1.0e-4 * right.abs());
        actual_bytes.extend_from_slice(&(left as f32).to_le_bytes());
    }
    let cosine = dot / (left_norm.sqrt() * right_norm.sqrt());
    assert!(cosine.is_finite(), "{label} cosine is non-finite");
    assert!(
        cosine >= 0.999_999,
        "{label} cosine {cosine} is below 0.999999"
    );
    assert_eq!(
        tolerance_failures, 0,
        "{label} has values outside atol=rtol=1e-4; maximum absolute error {maximum_absolute_error}"
    );
    Comparison {
        cosine,
        maximum_absolute_error,
        tolerance_failures,
        actual_sha256: sha256(&actual_bytes),
    }
}

/// Extracts F32 tensor values with a backend-capability diagnostic.
fn f32_values(data: TensorData, label: &str) -> Vec<f32> {
    data.to_vec::<f32>()
        .unwrap_or_else(|error| panic!("{label} did not expose F32 data: {error}"))
}

/// Returns the numerically greatest token, breaking exact ties by lower ID.
fn stable_top1(row: &[f32]) -> usize {
    assert!(!row.is_empty());
    let mut best = 0;
    for index in 1..row.len() {
        if row[index] > row[best] {
            best = index;
        }
    }
    best
}

/// Creates one unmasked token input.
fn input<B: Backend>(ids: &[i64], device: &B::Device) -> CausalLmInput<B> {
    CausalLmInput {
        token_ids: Tensor::<B, 2, Int>::from_data(
            TensorData::new(ids.to_vec(), [1, ids.len()]),
            device,
        ),
        token_mask: None,
        position_ids: None,
    }
}

/// Reconstructs the authenticated 512-token boundary input.
fn boundary_ids() -> Vec<i64> {
    let pattern = [71_i64, 8, 57];
    (0..511)
        .map(|index| pattern[index % pattern.len()])
        .chain([1])
        .collect()
}

/// Converts boundary IDs into their canonical acceptance digest.
fn u32le_ids_sha256(ids: &[i64]) -> String {
    let mut bytes = Vec::with_capacity(ids.len() * 4);
    for &id in ids {
        let id = u32::try_from(id).expect("nonnegative u32 boundary token");
        bytes.extend_from_slice(&id.to_le_bytes());
    }
    sha256(&bytes)
}

/// Resolves the opt-in model root.
fn checkpoint_root() -> PathBuf {
    PathBuf::from(
        std::env::var_os("TRANSFORMERS_FLAN_T5_SMALL_DIR").unwrap_or_else(|| {
            panic!("set TRANSFORMERS_FLAN_T5_SMALL_DIR to {REPOSITORY} revision {REVISION}")
        }),
    )
}

/// Resolves the opt-in official reference bundle.
fn reference_root() -> PathBuf {
    PathBuf::from(
        std::env::var_os("TRANSFORMERS_FLAN_T5_SMALL_REFERENCE_DIR").unwrap_or_else(|| {
            panic!("set TRANSFORMERS_FLAN_T5_SMALL_REFERENCE_DIR to the pinned reference bundle")
        }),
    )
}

/// Runs the complete release gate on one backend.
fn run_reference_gate<B: Backend>(device: &B::Device, backend: &str) {
    let reference = ReferenceBundle::open(&reference_root());
    let root = authenticate_checkpoint(&checkpoint_root());
    let started = Instant::now();
    let loaded = AutoSeq2SeqLm::<B>::load_local(
        &root,
        &AutoLoadOptions {
            repository: Some(REPOSITORY.into()),
            revision: Some(REVISION.into()),
            ..AutoLoadOptions::default()
        },
        device,
    )
    .expect("strictly load FLAN-T5-small through the public automatic API");
    let load_seconds = started.elapsed().as_secs_f64();
    assert_eq!(loaded.source().repository(), Some(REPOSITORY));
    assert_eq!(loaded.source().revision(), Some(REVISION));
    assert_eq!(loaded.load_report().applied.len(), 190);
    assert_eq!(loaded.load_report().transformed.len(), 145);
    assert!(loaded.load_report().missing.is_empty());
    assert!(loaded.load_report().unexpected.is_empty());
    let stats = loaded
        .execution_stats()
        .expect("automatic loader execution audit");
    assert_eq!(stats.source.shard_opens, 1);
    assert_eq!(stats.source.max_open_shards, 1);
    assert_eq!(loaded.generation_defaults().eos_token_ids, [1]);
    assert_eq!(loaded.generation_defaults().pad_token_id, Some(0));

    let tokenizer = loaded
        .tokenizer()
        .expect("load tokenizer.json through the public API");
    let encoded_long = tokenizer
        .encode(LONG_PROMPT, &EncodeOptions::default())
        .expect("tokenize long acceptance prompt");
    assert_eq!(
        encoded_long.token_ids(),
        &[LONG_SOURCE_IDS
            .iter()
            .map(|&id| id as u32)
            .collect::<Vec<_>>()]
    );
    let source = encoded_long
        .to_causal_input::<B>(device)
        .expect("convert long prompt to Burn tensors");
    let start = input::<B>(&[0], device);
    let diagnostics = ForwardOptions {
        logits: LogitsSelection::All,
        hidden_states: true,
        ..ForwardOptions::default()
    };
    let started = Instant::now();
    let stateless = loaded
        .model()
        .forward(
            Seq2SeqInput {
                encoder: source.clone(),
                decoder: start.clone(),
            },
            &diagnostics,
        )
        .expect("official prompt stateless forward");
    let stateless_seconds = started.elapsed().as_secs_f64();
    let encoder_comparison = compare(
        "encoder final",
        &f32_values(stateless.encoder.hidden_state.into_data(), "encoder final"),
        &reference.tensor("encoder_final"),
    );
    let decoder_comparison = compare(
        "decoder first final",
        &f32_values(
            stateless
                .decoder
                .final_hidden_state
                .expect("requested final decoder hidden")
                .into_data(),
            "decoder first final",
        ),
        &reference.tensor("decoder_first_final"),
    );
    let first_actual = f32_values(stateless.decoder.logits.into_data(), "first logits");
    let first_reference = reference.tensor("first_logits");
    let first_comparison = compare("first logits", &first_actual, &first_reference);
    assert_eq!(stable_top1(&first_actual), GREEDY_IDS[0] as usize);

    let encoder = loaded
        .model()
        .encode(source.clone(), &ForwardOptions::default())
        .expect("encode once for cached decoding");
    let mut state = loaded
        .model()
        .new_decode_state(
            CacheConfig::new(1, GREEDY_DECISIONS).expect("cache geometry"),
            1,
            device,
        )
        .expect("allocate T5 decode state");
    let last_only = ForwardOptions {
        logits: LogitsSelection::Last,
        ..ForwardOptions::default()
    };
    let cached_reference = reference.tensor("cached_logits");
    let started = Instant::now();
    let prefill = loaded
        .model()
        .prefill_decoder(&encoder, start, &mut state, &last_only)
        .expect("prefill decoder start token");
    let mut cached_actual = f32_values(prefill.decoder.logits.into_data(), "cached decision 0");
    assert_eq!(stable_top1(&cached_actual), GREEDY_IDS[0] as usize);
    for decision in 1..GREEDY_DECISIONS {
        let output = loaded
            .model()
            .decode(
                &encoder,
                DecodeInput {
                    token_ids: Tensor::<B, 2, Int>::from_data(
                        TensorData::new(vec![i64::from(GREEDY_IDS[decision - 1])], [1, 1]),
                        device,
                    ),
                    token_mask: None,
                    position_ids: None,
                },
                &mut state,
                &last_only,
            )
            .unwrap_or_else(|error| panic!("cached decision {decision}: {error}"));
        let row = f32_values(output.decoder.logits.into_data(), "cached decision logits");
        assert_eq!(
            stable_top1(&row),
            GREEDY_IDS[decision] as usize,
            "cached decision {decision}"
        );
        cached_actual.extend(row);
    }
    let cached_seconds = started.elapsed().as_secs_f64();
    assert_eq!(state.lengths(), [GREEDY_DECISIONS]);
    let cached_comparison = compare("cached logits", &cached_actual, &cached_reference);

    let teacher_ids = std::iter::once(0_i64)
        .chain(
            GREEDY_IDS[..GREEDY_DECISIONS - 1]
                .iter()
                .map(|&id| i64::from(id)),
        )
        .collect::<Vec<_>>();
    let started = Instant::now();
    let teacher = loaded
        .model()
        .forward(
            Seq2SeqInput {
                encoder: source,
                decoder: input::<B>(&teacher_ids, device),
            },
            &ForwardOptions {
                logits: LogitsSelection::All,
                ..ForwardOptions::default()
            },
        )
        .expect("teacher-forced stateless forward");
    let teacher_seconds = started.elapsed().as_secs_f64();
    let teacher_actual = f32_values(teacher.decoder.logits.into_data(), "teacher logits");
    for decision in 0..GREEDY_DECISIONS {
        let row = &teacher_actual[decision * VOCABULARY_SIZE..(decision + 1) * VOCABULARY_SIZE];
        assert_eq!(
            stable_top1(row),
            GREEDY_IDS[decision] as usize,
            "teacher decision {decision}"
        );
    }
    let teacher_comparison = compare(
        "teacher logits",
        &teacher_actual,
        &reference.tensor("teacher_logits"),
    );

    let padded = tokenizer
        .encode_batch(
            &[TRANSLATION_PROMPT, PADDED_SECOND_PROMPT],
            &EncodeOptions {
                padding: Padding::Longest,
                ..EncodeOptions::default()
            },
        )
        .expect("right-pad two FLAN inputs");
    assert_eq!(
        padded.token_ids()[0],
        TRANSLATION_IDS
            .iter()
            .map(|&id| id as u32)
            .collect::<Vec<_>>()
    );
    assert_eq!(
        padded.token_ids()[1],
        PADDED_SECOND_IDS
            .iter()
            .map(|&id| id as u32)
            .chain([0, 0, 0])
            .collect::<Vec<_>>()
    );
    assert_eq!(
        padded.valid_tokens()[1],
        [
            true, true, true, true, true, true, true, true, false, false, false
        ]
    );
    let padded_output = loaded
        .model()
        .forward(
            Seq2SeqInput {
                encoder: padded
                    .to_causal_input::<B>(device)
                    .expect("padded source tensors"),
                decoder: CausalLmInput {
                    token_ids: Tensor::<B, 2, Int>::from_data(
                        TensorData::new(vec![0_i64; 2], [2, 1]),
                        device,
                    ),
                    token_mask: None,
                    position_ids: None,
                },
            },
            &last_only,
        )
        .expect("right-padded batch forward");
    let padded_comparison = compare(
        "padded first logits",
        &f32_values(
            padded_output.decoder.logits.into_data(),
            "padded first logits",
        ),
        &reference.tensor("padded_first_logits"),
    );

    let boundary = boundary_ids();
    assert_eq!(boundary.len(), 512);
    assert_eq!(u32le_ids_sha256(&boundary), BOUNDARY_IDS_SHA256);
    let started = Instant::now();
    let boundary_output = loaded
        .model()
        .forward(
            Seq2SeqInput {
                encoder: input::<B>(&boundary, device),
                decoder: input::<B>(&[0], device),
            },
            &last_only,
        )
        .expect("512-token declared source boundary forward");
    let boundary_seconds = started.elapsed().as_secs_f64();
    let boundary_comparison = compare(
        "boundary first logits",
        &f32_values(
            boundary_output.decoder.logits.into_data(),
            "boundary first logits",
        ),
        &reference.tensor("boundary_first_logits"),
    );

    let translation = tokenizer
        .encode(TRANSLATION_PROMPT, &EncodeOptions::default())
        .expect("tokenize beam prompt")
        .to_causal_input::<B>(device)
        .expect("beam source tensors");
    let beam_started = Instant::now();
    let beam = match loaded.model() {
        AutoSeq2SeqLm::T5(model) => generate_t5_beam_search(
            model,
            translation,
            T5BeamSearchOptions {
                max_new_tokens: 16,
                num_beams: 4,
                num_return_sequences: 1,
                length_penalty: 1.0,
                early_stopping: false,
            },
        ),
        #[allow(unreachable_patterns)]
        _ => panic!("automatic seq2seq loader dispatched a non-T5 checkpoint"),
    }
    .expect("cached four-beam FLAN generation");
    let beam_seconds = beam_started.elapsed().as_secs_f64();
    assert_eq!(beam.sequences.len(), 1);
    assert_eq!(beam.sequences[0].len(), 1);
    assert_eq!(beam.sequences[0][0].token_ids, BEAM_IDS);
    assert_eq!(
        beam.sequences[0][0].finish_reason,
        FinishReason::EndOfSequence { token_id: 1 }
    );
    assert_eq!(reference.greedy_ids(), GREEDY_IDS);

    eprintln!(
        "FLAN-T5-small {backend}: load={load_seconds:.3}s stateless={stateless_seconds:.3}s \
         cached32={cached_seconds:.3}s teacher32={teacher_seconds:.3}s boundary512={boundary_seconds:.3}s \
         beam={beam_seconds:.3}s"
    );
    for (label, comparison) in [
        ("encoder", encoder_comparison),
        ("decoder", decoder_comparison),
        ("first", first_comparison),
        ("cached", cached_comparison),
        ("teacher", teacher_comparison),
        ("padded", padded_comparison),
        ("boundary", boundary_comparison),
    ] {
        eprintln!(
            "FLAN-T5-small {backend} {label}: cosine={:.12} max_abs={:.9} failures_1e-4={} actual_f32le_sha256={}",
            comparison.cosine,
            comparison.maximum_absolute_error,
            comparison.tolerance_failures,
            comparison.actual_sha256,
        );
    }
}

/// Validates the external oracle without allocating model parameters.
#[test]
#[ignore = "requires the pinned external FLAN-T5-small reference bundle"]
fn validates_pinned_flan_t5_small_reference_bundle() {
    let reference = ReferenceBundle::open(&reference_root());
    assert_eq!(reference.greedy_ids(), GREEDY_IDS);
}

/// Strictly loads FLAN-T5-small on Flex and matches every official F32 path.
#[cfg(feature = "flex")]
#[test]
#[ignore = "requires the pinned FLAN-T5-small checkpoint and reference bundle"]
fn flan_t5_small_flex_matches_official_reference() {
    run_reference_gate::<Flex<f32, i32>>(&Default::default(), "Flex/F32");
}

/// Strictly loads FLAN-T5-small on Metal and matches every official F32 path.
#[cfg(all(feature = "metal", target_os = "macos"))]
#[test]
#[ignore = "requires the pinned FLAN-T5-small checkpoint, reference bundle, and Metal"]
fn flan_t5_small_metal_matches_official_reference() {
    run_reference_gate::<Metal>(&Default::default(), "Metal/F32");
}

/// Pure helpers preserve tie semantics and the committed boundary digest.
#[test]
fn reference_math_contract_is_stable() {
    assert_eq!(stable_top1(&[0.0, -0.0, 0.0]), 0);
    assert_eq!(stable_top1(&[-1.0, 2.0, 2.0]), 1);
    let ids = boundary_ids();
    assert_eq!(ids.len(), 512);
    assert_eq!(u32le_ids_sha256(&ids), BOUNDARY_IDS_SHA256);
    let comparison = compare("identity", &[1.0, -2.0, 3.0], &[1.0, -2.0, 3.0]);
    assert_eq!(comparison.cosine, 1.0);
    assert_eq!(comparison.maximum_absolute_error, 0.0);
    assert_eq!(comparison.tolerance_failures, 0);
}

/// A proportional logit error preserves cosine and top-1 but must fail F32 elementwise parity.
#[test]
#[should_panic(expected = "has values outside atol=rtol=1e-4")]
fn reference_parity_rejects_scaled_logits_with_perfect_cosine() {
    let expected = [1.0_f32, -2.0, 3.0];
    let actual = expected.map(|value| value * 1.001);
    assert_eq!(stable_top1(&actual), stable_top1(&expected));
    compare("scaled logits", &actual, &expected);
}
